<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$id=(int)($_GET['id']??0);$row=$id?$pdo->query("SELECT * FROM produtos WHERE id=$id")->fetch():null;$cats=$pdo->query('SELECT * FROM categorias WHERE ativo=1 ORDER BY nome')->fetchAll();$pageTitle=$row?'Editar produto':'Novo produto';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$codigo=trim($_POST['codigo']??'');$barcode=trim($_POST['codigo_barras']??'');$nome=trim($_POST['nome']??'');$cat=(int)($_POST['categoria_id']??0);$desc=trim($_POST['descricao']??'');$custo=number_value($_POST['custo']??0);$preco=number_value($_POST['preco']??0);$min=number_value($_POST['estoque_minimo']??0);$un=trim($_POST['unidade']??'UN');if(!$codigo||!$nome){$error='Código e nome são obrigatórios.';}elseif($custo<0||$preco<0||$min<0){$error='Valores não podem ser negativos.';}else{try{$now=now();if($id){$pdo->prepare('UPDATE produtos SET codigo=?,codigo_barras=?,nome=?,categoria_id=?,descricao=?,custo=?,preco=?,estoque_minimo=?,unidade=?,atualizado_em=? WHERE id=?')->execute([$codigo,$barcode,$nome,$cat?:null,$desc,$custo,$preco,$min,$un,$now,$id]);log_action('alteração de produto','produtos',$id);}else{$pdo->prepare('INSERT INTO produtos(codigo,codigo_barras,nome,categoria_id,descricao,custo,preco,estoque,estoque_minimo,unidade,ativo,criado_em,atualizado_em) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$codigo,$barcode,$nome,$cat?:null,$desc,$custo,$preco,0,$min,$un,1,$now,$now]);$id=(int)$pdo->lastInsertId();log_action('criação de produto','produtos',$id);}flash('success','Produto salvo com sucesso.');redirect('index.php');}catch(Throwable $e){$error='Não foi possível salvar. Confira o código interno.';}}}
include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><div><h1><?=e($pageTitle)?></h1></div><a class="btn secondary" href="index.php">Voltar</a></div><div class="card"><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="field col-3"><label>Código interno</label><input name="codigo" required value="<?=e($row['codigo']??'')?>"></div><div class="field col-3"><label>Código de barras</label><input name="codigo_barras" value="<?=e($row['codigo_barras']??'')?>"></div><div class="field col-6"><label>Nome</label><input name="nome" required value="<?=e($row['nome']??'')?>"></div><div class="field col-4"><label>Categoria</label><select name="categoria_id"><option value="0">Sem categoria</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=((int)($row['categoria_id']??0)===$c['id'])?'selected':''?>><?=e($c['nome'])?></option><?php endforeach; ?></select></div><div class="field col-4"><label>Custo</label><input type="number" step="0.01" min="0" name="custo" value="<?=e($row['custo']??'0')?>"></div><div class="field col-4"><label>Preço de venda</label><input type="number" step="0.01" min="0" name="preco" value="<?=e($row['preco']??'0')?>"></div><div class="field col-3"><label>Estoque mínimo</label><input type="number" step="0.01" min="0" name="estoque_minimo" value="<?=e($row['estoque_minimo']??'0')?>"></div><div class="field col-3"><label>Unidade</label><input name="unidade" value="<?=e($row['unidade']??'UN')?>"></div><div class="field col-12"><label>Descrição</label><textarea name="descricao"><?=e($row['descricao']??'')?></textarea></div></div><div class="form-actions"><button class="btn primary">Salvar produto</button></div></form></div><?php include __DIR__.'/../../includes/footer.php'; ?>
